import { useCallback, useMemo } from 'react';

import type { KpiGroup } from 'domain/Kpi';
import { useBffData } from 'hooks';
import type { FilterForm } from 'models/Filters';

import { BigNumbersSectionData } from '../../../types';
import { UseBigNumberData } from '../../types';
import { getCommercialResultsSubFilters } from '../../utils/getCommercialResultsSubFilters';

const BFF_VIEW_ID = 'value-creation_commercial-results_big-numbers';
const BFF_COMPONENT_ID = 'big-numbers';

export const useBigNumberData = ({
  formatMessage,
  kpiGroup,
  periodValues,
  appliedPeriods,
  applied,
  onFilterChange,
}: {
  formatMessage: (descriptor: { id: string }) => string;
  kpiGroup: KpiGroup;
  periodValues: readonly string[];
  appliedPeriods: string;
  applied: FilterForm;
  onFilterChange: (key: string, value: string) => void;
}): UseBigNumberData => {
  const subFilters = useMemo(
    () => getCommercialResultsSubFilters(applied),
    [applied],
  );

  const bffData = useBffData({
    id: BFF_VIEW_ID,
    kpiGroup,
    subFilters,
  });

  const bigNumbersData = useMemo((): BigNumbersSectionData[] => {
    const raw = bffData.data?.[BFF_COMPONENT_ID];
    return Array.isArray(raw) ? (raw as BigNumbersSectionData[]) : [];
  }, [bffData.data]);

  const title = useMemo(() => {
    return formatMessage({
      id: 'ValueCreation.CommercialResults.bigNumbers.title',
    });
  }, [formatMessage]);

  const selectedBigNumberIndex = useMemo(() => {
    const index = periodValues.indexOf(appliedPeriods);
    return Math.max(index, 0);
  }, [appliedPeriods, periodValues]);

  const handleBigNumbersSelect = useCallback(
    (index: number) => {
      if (bigNumbersData?.[index]) {
        onFilterChange('periods', periodValues[index]);
      }
    },
    [onFilterChange, periodValues, bigNumbersData],
  );

  return {
    bigNumbersData,
    loading: bffData.loading,
    error: bffData.error,
    title,
    selectedBigNumberIndex,
    handleBigNumbersSelect,
  };
};
